:hasAmount a owl:FunctionalProperty .
:hasReferenceNumber a owl:FunctionalProperty .
:assignedToBusinessProcess a owl:FunctionalProperty .
:alignedWithStandard a owl:FunctionalProperty .

#################################################################
# INVOICE SUMMATION (ANNOTATION)
#################################################################
:InvoiceMessage rdfs:comment "The sum of the amounts (net price × quantity + tax) for all invoice lines should equal the total amount in the summary section. This constraint can be validated by SHACL or external rules."@en .

